  "check_code": "import sqlite3
from pathlib import Path


SYSTEM = "shell_asset_valuation_workbench"
TARGET = "APV-2024-NS-011"
OLD_UPDATED_AT = "2025-01-10T17:20:00Z"


def _root(ws):
    return Path(ws).resolve().parent


def _db_path(ws):
    return _root(ws) / "system" / SYSTEM / "state.db"


def _backup_path(ws):
    return _root(ws) / "system" / SYSTEM / "state.db.pinned_backup"


def _rows(path, query, params=()):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(query, params).fetchall()]
    finally:
        connection.close()


def check_target_workflow_corrected(ws):
    try:
        rows = _rows(
            _db_path(ws),
            "SELECT review_status, committee_decision, decision_date, conclusion_type, updated_at "
            "FROM valuation_approval_log WHERE approval_id = ?",
            (TARGET,),
        )
    except Exception as exc:
        return {"score": 0, "detail": f"无法读取目标审批记录: {exc}"}
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标审批记录数={len(rows)}，应为1"}
    row = rows[0]
    expected = {
        "review_status": "Reviewed",
        "committee_decision": "Pending",
        "decision_date": None,
        "conclusion_type": "MODEL_SCREENING_ONLY",
    }
    mismatches = [key for key, value in expected.items() if row.get(key) != value]
    if mismatches:
        return {"score": 0, "detail": f"目标工作流字段不符: {mismatches}; current={row}"}
    if row["updated_at"] == OLD_UPDATED_AT:
        return {"score": 0, "detail": "目标记录更新时间未变化，未完成受控更新"}
    return {"score": 1, "detail": "目标记录已更正为 Reviewed/Pending，决定日期为空且保持模型筛查性质"}


def check_unrelated_records_preserved(ws):
    current_path = _db_path(ws)
    backup_path = _backup_path(ws)
    if not backup_path.exists():
        return {"score": 0, "detail": "缺少固定基线数据库，无法核验未涉及记录"}
    try:
        baseline_approvals = {
            row["approval_id"]: row
            for row in _rows(backup_path, "SELECT * FROM valuation_approval_log")
        }
        current_approvals = {
            row["approval_id"]: row
            for row in _rows(current_path, "SELECT * FROM valuation_approval_log")
        }
        if set(current_approvals) != set(baseline_approvals):
            return {"score": 0, "detail": "审批记录被新增或删除"}
        for approval_id, baseline in baseline_approvals.items():
            current = current_approvals[approval_id]
            if approval_id == TARGET:
                for field, value in baseline.items():
                    if field in {"review_status", "updated_at"}:
                        continue
                    if current.get(field) != value:
                        return {"score": 0, "detail": f"目标记录非许可字段被修改: {field}"}
            elif current != baseline:
                return {"score": 0, "detail": f"非目标审批记录被修改: {approval_id}"}
        for table in ("cgu_master", "valuation_measurement_detail"):
            baseline = _rows(backup_path, f"SELECT * FROM {table} ORDER BY 1")
            current = _rows(current_path, f"SELECT * FROM {table} ORDER BY 1")
            if current != baseline:
                return {"score": 0, "detail": f"关联基础数据被修改: {table}"}
    except Exception as exc:
        return {"score": 0, "detail": f"未涉及记录核验失败: {exc}"}
    return {"score": 1, "detail": "仅目标记录的技术审阅状态与更新时间发生变化"}
